using System.Collections.Generic;using System.Text;public class Solution{string K(string s){var r=new StringBuilder();foreach(char c in s)r.Append((char)('a'+(c-s[0]+26)%26));return r.ToString();}public IList<IList<string>> GroupStrings(string[]s){var m=new Dictionary<string,List<string>>();foreach(var x in s){var k=K(x);if(!m.ContainsKey(k))m[k]=new();m[k].Add(x);}var o=new List<IList<string>>();foreach(var v in m.Values)o.Add(v);return o;}}
